<?php
require __DIR__.'/../private/bootstrap.php';require __DIR__.'/../private/article-fetch.php';
foreach(['http://127.0.0.1/x','http://169.254.169.254/x','http://10.0.0.1/','http://100.100.1.1/','http://[::1]/','http://user:pass@example.com/','file:///etc/passwd','http://example.com:22/'] as $url){try{article_public_host($url);throw new RuntimeException('unsafe URL accepted');}catch(AppError $e){}}
$html='<html><head><title>Test</title></head><body><nav>Ignore navigation</nav><article><h1>Eine Meldung</h1><p>'.str_repeat('Ein vollständiger Artikel mit überprüfbaren Fakten. ',10).'</p><script>secretScript()</script><p hidden>Ignore hidden</p></article></body></html>';
$r=article_extract($html);assert($r['title']==='Eine Meldung');assert(!str_contains($r['content'],'Ignore'));assert(!str_contains($r['content'],'secretScript'));
try{article_extract(str_replace('<head>','<head><script type="application/ld+json">{"isAccessibleForFree":false}</script>',$html));throw new RuntimeException('paywall accepted');}catch(AppError $e){}
$teaser='<html><head><title>HAZ regression fixture</title></head><body><article><h1>Testartikel</h1><section itemprop="articleBody" class="t-article-body"><div class="u-blur-crop"><p>Ein kurzer Vorschautext…</p></div></section><aside>'.str_repeat('Begleittext außerhalb des Artikels. ',20).'</aside><div class="comments">'.str_repeat('Ein Leserkommentar. ',20).'</div></article></body></html>';
try{article_extract($teaser);throw new RuntimeException('HAZ teaser accepted');}catch(AppError $e){assert(str_contains($e->getMessage(),'anmelden'));}
$free='<html><head><title>Frei</title></head><body><header><a href="/login">Anmelden</a></header><article><h1>Freier Artikel</h1><section itemprop="articleBody"><p>'.str_repeat('Vollständiger frei zugänglicher Testtext. ',10).'</p></section><div class="comments">KEIN KOMMENTAR IM TEXT</div></article></body></html>';
$r=article_extract($free);assert($r['title']==='Freier Artikel');assert(!str_contains($r['content'],'KEIN KOMMENTAR'));assert(!str_contains($r['content'],'Anmelden'));
try{article_extract(str_replace('<head>','<head><meta itemprop="isAccessibleForFree" content="false">',$free));throw new RuntimeException('Microdata restriction accepted');}catch(AppError $e){}
try{article_extract(str_replace('Vollständiger frei zugänglicher Testtext. ','Um diesen Artikel zu lesen, bitte anmelden. ',$free));throw new RuntimeException('Login prompt accepted');}catch(AppError $e){}
echo "PASS: private/reserved/credential URL rejection, semantic extraction, hidden/script removal and subscription barrier detection, HAZ blur/crop teaser, microdata, body-only extraction and free pages with navigation login links.\n";
